const retrievedItems = $input.all();

if (retrievedItems.length === 0) {
  throw new Error(
    'Baseline retrieval returned no documents.'
  );
}

// Retrieve the evaluation question that produced
// the current set of Pinecone results.
const testCase =
  $('Loop Through Evaluation Questions')
    .itemMatching(0)
    .json;

const baselineResults = retrievedItems.map(
  (item, index) => {
    const result = item.json;

    const document =
      result.document || result;

    const metadata =
      document.metadata ||
      result.metadata ||
      {};

    const pageContent = String(
      document.pageContent ||
      result.pageContent ||
      result.text ||
      ''
    ).trim();

    return {
      rank: index + 1,

      similarity_score:
        result.score ?? null,

      page_content:
        pageContent,

      ticker:
        metadata.ticker ?? null,

      company_name:
        metadata.company_name ?? null,

      form_type:
        metadata.form_type ?? null,

      filing_date:
        metadata.filing_date ?? null,

      accession_number:
        metadata.accession_number ?? null,

      source_url:
        metadata.source_url ?? null,

      document_id:
        metadata.document_id ?? null
    };
  }
);

return [
  {
    json: {
      test_id:
        testCase.test_id,

      question:
        testCase.question,

      expected_topics:
        testCase.expected_topics,

      expected_ticker:
        testCase.expected_ticker,

      expected_form_type:
        testCase.expected_form_type,

      baseline_retrieved_count:
        baselineResults.length,

      baseline_results:
        baselineResults
    }
  }
];

const enhancedItems = $input.all();

if (enhancedItems.length === 0) {
  throw new Error(
    'Enhanced retrieval returned no documents.'
  );
}

// Follow the current loop iteration back to the
// baseline evaluation record for this question.
const baselineRecord =
  $('Capture Baseline Results')
    .itemMatching(0)
    .json;

const enhancedResults = enhancedItems.map(
  (item, index) => {
    const result =
      item.json;

    const document =
      result.document ||
      result;

    const metadata =
      document.metadata ||
      result.metadata ||
      {};

    const pageContent =
      String(
        document.pageContent ||
        result.pageContent ||
        result.text ||
        ''
      ).trim();

    return {
      rank:
        index + 1,

      rerank_score:
        result.score ?? null,

      page_content:
        pageContent,

      ticker:
        metadata.ticker ?? null,

      company_name:
        metadata.company_name ?? null,

      form_type:
        metadata.form_type ?? null,

      filing_date:
        metadata.filing_date ?? null,

      accession_number:
        metadata.accession_number ?? null,

      source_url:
        metadata.source_url ?? null,

      document_id:
        metadata.document_id ?? null
    };
  }
);

return [
  {
    json: {
      ...baselineRecord,

      enhanced_retrieved_count:
        enhancedResults.length,

      enhanced_results:
        enhancedResults
    }
  }
];

const evaluationRecords =
  $input.all().map(item => item.json);

if (evaluationRecords.length === 0) {
  throw new Error(
    'No completed evaluation records were received.'
  );
}

/*
 * This alias map makes the automatic evaluation more robust
 * than exact phrase matching alone.
 */
const topicAliases = {
  'outsourced manufacturing': [
    'outsourced manufacturing',
    'contract manufacturers',
    'manufacturing partners',
    'third party manufacturing',
    'outsourced production'
  ],

  'supplier concentration': [
    'supplier concentration',
    'limited number of suppliers',
    'single source suppliers',
    'concentrated suppliers',
    'concentrate on the production'
  ],

  'component shortages': [
    'component shortages',
    'shortage of components',
    'supply shortages',
    'component availability',
    'obtain sufficient quantities'
  ],

  'price increases': [
    'price increases',
    'increased prices',
    'higher prices',
    'commercially reasonable terms'
  ],

  'share repurchases': [
    'share repurchases',
    'repurchase shares',
    'repurchased shares',
    'repurchase program',
    'stock repurchases'
  ],

  'common stock': [
    'common stock',
    'common shares'
  ],

  'capital return': [
    'capital return',
    'return capital',
    'capital return program',
    'return of capital'
  ],

  'dividends': [
    'dividends',
    'cash dividend',
    'dividend payments'
  ],

  'travel restrictions': [
    'travel restrictions',
    'employee travel',
    'restrictions on travel'
  ],

  'freight limitations': [
    'freight limitations',
    'limitations on freight',
    'freight services',
    'shipping limitations'
  ],

  'supply-chain disruption': [
    'supply chain disruption',
    'disrupt supply chains',
    'supply chain interruptions',
    'supply chain constraints'
  ],

  'production delays': [
    'production delays',
    'delays in production',
    'production ramps',
    'manufacturing delays'
  ],

  'security breaches': [
    'security breaches',
    'security breach',
    'cybersecurity incident',
    'unauthorized access',
    'cyber attacks'
  ],

  'data privacy': [
    'data privacy',
    'privacy laws',
    'personal information',
    'privacy regulations'
  ],

  'service disruption': [
    'service disruption',
    'disruption of services',
    'service interruptions',
    'systems unavailable'
  ],

  'reputational harm': [
    'reputational harm',
    'harm to reputation',
    'reputational damage',
    'damage its reputation'
  ],

  'competition': [
    'competition',
    'competitive markets',
    'competitors',
    'competitive pressure'
  ],

  'technological change': [
    'technological change',
    'rapid technological',
    'technology changes',
    'changing technology'
  ],

  'new product introductions': [
    'new product introductions',
    'introduce new products',
    'new products and services',
    'product introductions'
  ],

  'pricing pressure': [
    'pricing pressure',
    'price competition',
    'lower prices',
    'competitive pricing'
  ]
};

/*
 * Convert text into a normalized lowercase representation
 * without relying on regular expressions.
 */
function normalizeText(value) {
  const input =
    String(value || '').toLowerCase();

  let normalized = '';

  for (const character of input) {
    const code =
      character.charCodeAt(0);

    const isNumber =
      code >= 48 &&
      code <= 57;

    const isLetter =
      code >= 97 &&
      code <= 122;

    normalized +=
      isNumber || isLetter
        ? character
        : ' ';
  }

  return normalized
    .split(' ')
    .filter(part => part !== '')
    .join(' ');
}

function round(value, decimals = 2) {
  const factor =
    Math.pow(10, decimals);

  return Math.round(
    (value + Number.EPSILON) *
    factor
  ) / factor;
}

function average(values) {
  if (values.length === 0) {
    return 0;
  }

  return values.reduce(
    (total, value) =>
      total + value,
    0
  ) / values.length;
}

function findMatchedTopics(
  pageContent,
  expectedTopics
) {
  const normalizedPage =
    normalizeText(pageContent);

  return expectedTopics.filter(
    expectedTopic => {
      const aliases =
        topicAliases[expectedTopic] ||
        [expectedTopic];

      return aliases.some(alias =>
        normalizedPage.includes(
          normalizeText(alias)
        )
      );
    }
  );
}

function evaluateTopFive(
  results,
  expectedTopics,
  expectedTicker,
  expectedFormType
) {
  const topFive =
    (results || []).slice(0, 5);

  const evaluatedResults =
    topFive.map(
      (result, index) => {
        const matchedTopics =
          findMatchedTopics(
            result.page_content,
            expectedTopics
          );

        const tickerCorrect =
          !expectedTicker ||
          result.ticker ===
            expectedTicker;

        const formTypeCorrect =
          !expectedFormType ||
          result.form_type ===
            expectedFormType;

        return {
          rank:
            index + 1,

          score:
            result.rerank_score ??
            result.similarity_score ??
            null,

          relevant:
            matchedTopics.length > 0,

          matched_topics:
            matchedTopics,

          ticker_correct:
            tickerCorrect,

          form_type_correct:
            formTypeCorrect,

          metadata_correct:
            tickerCorrect &&
            formTypeCorrect,

          document_id:
            result.document_id ??
            null,

          filing_date:
            result.filing_date ??
            null,

          source_url:
            result.source_url ??
            null,

          passage_preview:
            String(
              result.page_content || ''
            ).slice(0, 300)
        };
      }
    );

  const relevantResults =
    evaluatedResults.filter(
      result => result.relevant
    );

  const metadataCorrectResults =
    evaluatedResults.filter(
      result =>
        result.metadata_correct
    );

  const matchedTopicSet =
    new Set();

  for (
    const evaluatedResult of
    evaluatedResults
  ) {
    for (
      const topic of
      evaluatedResult.matched_topics
    ) {
      matchedTopicSet.add(topic);
    }
  }

  const firstRelevantIndex =
    evaluatedResults.findIndex(
      result => result.relevant
    );

  return {
    top_k:
      evaluatedResults.length,

    relevant_chunk_count:
      relevantResults.length,

    top5_relevance_percent:
      evaluatedResults.length === 0
        ? 0
        : round(
            relevantResults.length *
            100 /
            evaluatedResults.length
          ),

    topics_matched:
      Array.from(matchedTopicSet),

    expected_topic_count:
      expectedTopics.length,

    matched_topic_count:
      matchedTopicSet.size,

    topic_coverage_percent:
      expectedTopics.length === 0
        ? 0
        : round(
            matchedTopicSet.size *
            100 /
            expectedTopics.length
          ),

    metadata_accuracy_percent:
      evaluatedResults.length === 0
        ? 0
        : round(
            metadataCorrectResults.length *
            100 /
            evaluatedResults.length
          ),

    reciprocal_rank:
      firstRelevantIndex === -1
        ? 0
        : round(
            1 /
            (
              firstRelevantIndex +
              1
            ),
            4
          ),

    results:
      evaluatedResults
  };
}

const testResults =
  evaluationRecords.map(record => {
    const expectedTopics =
      record.expected_topics || [];

    const baseline =
      evaluateTopFive(
        record.baseline_results,
        expectedTopics,
        record.expected_ticker,
        record.expected_form_type
      );

    const enhanced =
      evaluateTopFive(
        record.enhanced_results,
        expectedTopics,
        record.expected_ticker,
        record.expected_form_type
      );

    return {
      test_id:
        record.test_id,

      question:
        record.question,

      expected_topics:
        expectedTopics,

      baseline,

      enhanced,

      improvement: {
        relevance_percentage_points:
          round(
            enhanced
              .top5_relevance_percent -
            baseline
              .top5_relevance_percent
          ),

        topic_coverage_percentage_points:
          round(
            enhanced
              .topic_coverage_percent -
            baseline
              .topic_coverage_percent
          ),

        reciprocal_rank_change:
          round(
            enhanced.reciprocal_rank -
            baseline.reciprocal_rank,
            4
          )
      }
    };
  });

const baselineRelevance =
  testResults.map(
    result =>
      result
        .baseline
        .top5_relevance_percent
  );

const enhancedRelevance =
  testResults.map(
    result =>
      result
        .enhanced
        .top5_relevance_percent
  );

const baselineTopicCoverage =
  testResults.map(
    result =>
      result
        .baseline
        .topic_coverage_percent
  );

const enhancedTopicCoverage =
  testResults.map(
    result =>
      result
        .enhanced
        .topic_coverage_percent
  );

const baselineMetadataAccuracy =
  testResults.map(
    result =>
      result
        .baseline
        .metadata_accuracy_percent
  );

const enhancedMetadataAccuracy =
  testResults.map(
    result =>
      result
        .enhanced
        .metadata_accuracy_percent
  );

const baselineMrr =
  testResults.map(
    result =>
      result
        .baseline
        .reciprocal_rank
  );

const enhancedMrr =
  testResults.map(
    result =>
      result
        .enhanced
        .reciprocal_rank
  );

const summary = {
  evaluation_name:
    'WealthPlan SEC RAG retrieval evaluation',

  evaluation_method:
    'Automatic expected-topic and alias matching over the top five retrieved chunks. This is a transparent relevance proxy and should be manually reviewed before reporting final results.',

  test_case_count:
    testResults.length,

  chunks_reviewed: {
    baseline:
      testResults.length * 5,

    enhanced:
      testResults.length * 5
  },

  baseline: {
    average_top5_relevance_percent:
      round(
        average(
          baselineRelevance
        )
      ),

    average_topic_coverage_percent:
      round(
        average(
          baselineTopicCoverage
        )
      ),

    average_metadata_accuracy_percent:
      round(
        average(
          baselineMetadataAccuracy
        )
      ),

    mean_reciprocal_rank:
      round(
        average(
          baselineMrr
        ),
        4
      )
  },

  enhanced_with_reranking: {
    average_top5_relevance_percent:
      round(
        average(
          enhancedRelevance
        )
      ),

    average_topic_coverage_percent:
      round(
        average(
          enhancedTopicCoverage
        )
      ),

    average_metadata_accuracy_percent:
      round(
        average(
          enhancedMetadataAccuracy
        )
      ),

    mean_reciprocal_rank:
      round(
        average(
          enhancedMrr
        ),
        4
      )
  },

  reranking_lift: {
    relevance_percentage_points:
      round(
        average(
          enhancedRelevance
        ) -
        average(
          baselineRelevance
        )
      ),

    topic_coverage_percentage_points:
      round(
        average(
          enhancedTopicCoverage
        ) -
        average(
          baselineTopicCoverage
        )
      ),

    mrr_change:
      round(
        average(
          enhancedMrr
        ) -
        average(
          baselineMrr
        ),
        4
      )
  },

  target: {
    desired_top5_relevance_percent:
      80,

    achieved_by_enhanced_proxy:
      average(
        enhancedRelevance
      ) >= 80
  },

  manual_review_required:
    true
};

return [
  {
    json: {
      summary,
      test_results:
        testResults
    }
  }
];
